		void FindAttributesCore()
		{
			if (LinesGrid != null && LinesGrid.List != null)
			{
				if (LinesGrid.ListManager != null && LinesGrid.ListManager.Position >= 0)
				{
					var docketLine = (WhsDocketLine)LinesGrid.ListManager.GetCurrent();
					if (docketLine != null)
					{
						ChooseInventoryRecordFindAttributes(docketLine);
					}
				}
				else
				{
					Globals.Message.ShowError(Res.GetString("ad360b55-d450-49e1-8f3f-1fa9a84ed3ea", "Please enter a new row (by entering a value into any column) before using the Find Attributes option"));
				}
			}
		}

		void ChooseInventoryRecordFindAttributes(WhsDocketLine docketLine)
		{
			var docket = Docket;
			var inventoryCollection = new WhsInventoryViewCollection(docket.Factory);

			inventoryCollection.AddWarehouseClientProductFilterDefaults(docket.WD_WW_Whs, docket.WD_OH_Client, docketLine.WE_OP);
			inventoryCollection.AddAttributeFilterDefaults(docketLine);

			var recordChooser = new ZRecordChooser<WhsInventoryView>(ModuleIDs.WhsInventory, inventoryCollection);
			recordChooser.ShowModal(LinesGrid.FindForm(), delegate(WhsInventoryView[] selectedInventory)
			{
				if (selectedInventory.Length > 0)
				{
					using (new DocketNotificationSubscriber(Docket, GetNotificationBuffer()))
					{
						docketLine.UseChosenInventoryRowFindAttributes(selectedInventory[0]);
					}
				}
			});
		}

