		#region Grid_MouseDown

		void Grid_MouseDown(object sender, MouseEventArgs e)
		{
			Grid_MouseDownCore(e);
		}

		protected void Grid_MouseDownCore(MouseEventArgs e)
		{
			var hitInfo = LinesGrid.HitTest(e.X, e.Y);
			if (hitInfo.Row >= 0 && hitInfo.Row < LinesGrid.ListManager.List.Count)
			{
				if (e.Button == MouseButtons.Right)
				{
					LinesGrid.CurrentRowIndex = hitInfo.Row;
				}

				if (e.Clicks == 2 && e.Button == MouseButtons.Left)
				{
					OnDoubleClickDocketLine();
				}
			}
		}

		protected virtual void OnDoubleClickDocketLine()
		{
		}

